"use client";

import { useCallback, useEffect, useState } from "react";
import {
  Alert,
  Box,
  Button,
  Chip,
  MenuItem,
  Paper,
  Snackbar,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  Typography,
} from "@mui/material";
import { Save } from "@mui/icons-material";
import {
  Actions,
  EmptyRow,
  Field,
  FormGrid,
  PageHeading,
  api,
  currentUser,
  headSx,
  panelSx,
  useSearch,
} from "@/app/components/quejas/shared";
import { BRAND } from "@/libs/theme_palette";

const EMPTY = {
  sap: "",
  categoria: "SERIE",
  estandar_pack: "",
  clasificacion: "A",
  componente: "",
  plataforma: "",
  caracteristica_critica: "0",
  proveedor: "",
};
const COLUMNS = [
  "Acciones",
  "SAP",
  "Componente",
  "Categoría",
  "Clasificación",
  "Proveedor",
  "Plataforma",
  "Pack",
  "Crítica",
  "Estado",
];

export default function ComponentesCrud() {
  const [rows, setRows] = useState([]);
  const [form, setForm] = useState(EMPTY);
  const [editingId, setEditingId] = useState(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [showDeleted, setShowDeleted] = useState(false);
  const [search, setSearch] = useState("");
  const [notice, setNotice] = useState({ text: "", severity: "success" });
  const visible = useSearch(rows, search);
  const notify = useCallback(
    (text, severity = "success") => setNotice({ text, severity }),
    [],
  );

  const load = useCallback(async () => {
    setLoading(true);
    try {
      const result = await api(
        `/api/componentes${showDeleted ? "?eliminados=1" : ""}`,
      );
      setRows(result.data);
    } catch (error) {
      notify(error.message, "error");
    } finally {
      setLoading(false);
    }
  }, [notify, showDeleted]);

  useEffect(() => {
    const timer = setTimeout(load, 0);
    return () => clearTimeout(timer);
  }, [load]);

  const reset = () => {
    setForm(EMPTY);
    setEditingId(null);
  };

  const save = async (event) => {
    event.preventDefault();
    setSaving(true);
    try {
      await api("/api/componentes", {
        method: editingId ? "PUT" : "POST",
        body: JSON.stringify({
          ...form,
          id: editingId,
          usuario: currentUser(),
        }),
      });
      notify(editingId ? "Componente actualizado" : "Componente creado");
      reset();
      await load();
    } catch (error) {
      notify(error.message, "error");
    } finally {
      setSaving(false);
    }
  };

  const edit = (row) => {
    setEditingId(row.id);
    setForm(
      Object.fromEntries(
        Object.keys(EMPTY).map((key) => [key, String(row[key] ?? "")]),
      ),
    );
    window.scrollTo({ top: 0, behavior: "smooth" });
  };

  const toggle = async (row, method) => {
    if (
      method === "DELETE" &&
      !window.confirm(`¿Dar de baja el componente SAP ${row.sap}?`)
    ) {
      return;
    }
    try {
      await api("/api/componentes", {
        method,
        body: JSON.stringify({ id: row.id, usuario: currentUser() }),
      });
      notify(method === "PATCH" ? "Componente restaurado" : "Componente eliminado");
      await load();
    } catch (error) {
      notify(error.message, "error");
    }
  };

  return (
    <>
      <Paper component="form" onSubmit={save} elevation={0} sx={panelSx}>
        <Typography variant="h5" align="center" sx={{ mb: 2.5, fontWeight: 700 }}>
          {editingId ? `Editar componente #${editingId}` : "Nuevo componente"}
        </Typography>
        <FormGrid>
          <Field name="sap" label="SAP" form={form} setForm={setForm} required upper />
          <Field
            select
            name="categoria"
            label="Categoría"
            form={form}
            setForm={setForm}
            required
          >
            {["NUEVO", "SERIE", "SLOW_MOVER"].map((value) => (
              <MenuItem key={value} value={value}>
                {value}
              </MenuItem>
            ))}
          </Field>
          <Field
            select
            name="clasificacion"
            label="Clasificación"
            form={form}
            setForm={setForm}
            required
          >
            {["AA", "A", "B", "C"].map((value) => (
              <MenuItem key={value} value={value}>
                {value}
              </MenuItem>
            ))}
          </Field>
          <Box sx={{ gridColumn: { sm: "span 2" } }}>
            <Field
              name="componente"
              label="Componente"
              form={form}
              setForm={setForm}
              required
              upper
            />
          </Box>
          <Field
            name="proveedor"
            label="Proveedor"
            form={form}
            setForm={setForm}
            required
            upper
          />
          <Field
            name="plataforma"
            label="Plataforma"
            form={form}
            setForm={setForm}
            upper
          />
          <Field
            name="estandar_pack"
            label="Estándar pack"
            form={form}
            setForm={setForm}
            upper
          />
          <Field
            select
            name="caracteristica_critica"
            label="Característica crítica"
            form={form}
            setForm={setForm}
          >
            <MenuItem value="0">No</MenuItem>
            <MenuItem value="1">Sí</MenuItem>
          </Field>
        </FormGrid>
        <Box sx={{ display: "flex", justifyContent: "flex-end", gap: 1, mt: 2.5 }}>
          {editingId && (
            <Button variant="outlined" onClick={reset}>
              Cancelar
            </Button>
          )}
          <Button type="submit" variant="contained" startIcon={<Save />} disabled={saving}>
            {saving ? "Guardando..." : editingId ? "Actualizar" : "Guardar"}
          </Button>
        </Box>
      </Paper>

      <Paper elevation={0} sx={{ ...panelSx, mt: 2 }}>
        <PageHeading
          title="Catálogo de componentes"
          description="Administra SAP, clasificación y datos maestros."
          search={search}
          setSearch={setSearch}
          showDeleted={showDeleted}
          setShowDeleted={setShowDeleted}
        />
        <TableContainer>
          <Table size="small">
            <TableHead>
              <TableRow sx={{ bgcolor: BRAND.navy }}>
                {COLUMNS.map((heading) => (
                  <TableCell key={heading} sx={headSx}>
                    {heading}
                  </TableCell>
                ))}
              </TableRow>
            </TableHead>
            <TableBody>
              {!visible.length ? (
                <EmptyRow columns={COLUMNS.length} loading={loading} />
              ) : (
                visible.map((row) => (
                  <TableRow key={row.id} hover sx={{ opacity: row.eliminado_en ? 0.55 : 1 }}>
                    <TableCell>
                      <Actions
                        row={row}
                        onEdit={edit}
                        onDelete={(item) => toggle(item, "DELETE")}
                        onRestore={(item) => toggle(item, "PATCH")}
                      />
                    </TableCell>
                    <TableCell>{row.sap}</TableCell>
                    <TableCell>{row.componente}</TableCell>
                    <TableCell>{row.categoria}</TableCell>
                    <TableCell>
                      <Chip size="small" color="primary" label={row.clasificacion} />
                    </TableCell>
                    <TableCell>{row.proveedor}</TableCell>
                    <TableCell>{row.plataforma || "—"}</TableCell>
                    <TableCell>{row.estandar_pack || "—"}</TableCell>
                    <TableCell>{Number(row.caracteristica_critica) ? "Sí" : "No"}</TableCell>
                    <TableCell>{row.eliminado_en ? "ELIMINADO" : "ACTIVO"}</TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </TableContainer>
      </Paper>
      <Snackbar
        open={Boolean(notice.text)}
        autoHideDuration={4500}
        onClose={() => setNotice((value) => ({ ...value, text: "" }))}
      >
        <Alert severity={notice.severity} variant="filled">
          {notice.text}
        </Alert>
      </Snackbar>
    </>
  );
}
